export function summarizeLocalPackageNewUserSource(start, end) {
  const sourceRows = LOCAL_PACKAGE_DAILY_SOURCE.filter(row => row.date >= start && row.date <= end);
  const excluded = sourceRows.filter(row => ANDROID_NEW_USER_EXCLUSIONS[row.date]).map(row => ({ date: row.date, reason: ANDROID_NEW_USER_EXCLUSIONS[row.date] }));
  const rows = sourceRows.filter(row => !ANDROID_NEW_USER_EXCLUSIONS[row.date]);
  const totals = rows.length ? Object.fromEntries(Object.keys(LOCAL_PACKAGE_DAILY_SOURCE[0].raw.total).map(key => [key, rows.reduce((sum, row) => sum + row.raw.total[key], 0)])) : null;
  return { sourceDates: sourceRows.map(row => row.date), includedDates: rows.map(row => row.date), excluded, totals };
}
